@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + number : int
  + capacity : int
}

class Person {
  + firstName : string
  + lastName : string
  + birthDate : date
}

class Trainer extends Person {
  + diploma : string
}

class Session {
  + date : date
  + startingHour : time
}

class GroupSession extends Session {
  + type : string
}

class IndividualSession extends Session {}

class Participation {
}

Center "1" *-- "1..*" Room
Center "1" -- "*" Session
Room "1" -- "*" Session
Person "1" -- "*" Participation
Session "1" -- "*" Participation
Session "0..1" -- "1" Trainer : supervised

@enduml

